describe('errore + DisposableStack integration', () => {
    test('defer cleanup with errore error handling pattern', async () => {
        const log = [];
        class DbError extends Error {
            _tag = 'DbError';
        }
        async function processRequest() {
            const env_7 = { stack: [], error: void 0, hasError: false };
            try {
                const cleanup = __addDisposableResource(env_7, new AsyncDisposableStack()
                // Simulate acquiring resources
                , true);
                // Simulate acquiring resources
                const db = { connected: true };
                cleanup.defer(async () => {
                    log.push('db closed');
                    db.connected = false;
                });
                const cache = { open: true };
                cleanup.defer(async () => {
                    log.push('cache flushed');
                    cache.open = false;
                });
                // Simulate an error mid-operation
                if (!db.connected)
                    return new DbError('not connected');
                log.push('work done');
                return 'success';
            }
            catch (e_7) {
                env_7.error = e_7;
                env_7.hasError = true;
            }
            finally {
                const result_4 = __disposeResources(env_7);
                if (result_4)
                    await result_4;
            }
        }
        const result = await processRequest();
        expect(result).toBe('success');
        expect(log).toMatchInlineSnapshot(`
      [
        "work done",
        "cache flushed",
        "db closed",
      ]
    `);
    });
    test('cleanup runs even when returning error early', async () => {
        const log = [];
        class ConnectionError extends Error {
            _tag = 'ConnectionError';
        }
        async function riskyOp() {
            const env_8 = { stack: [], error: void 0, hasError: false };
            try {
                const cleanup = __addDisposableResource(env_8, new AsyncDisposableStack(), true);
                const resource = { released: false };
                cleanup.defer(() => {
                    resource.released = true;
                    log.push('released');
                });
                // Early return with error — cleanup still runs
                return new ConnectionError('failed');
            }
            catch (e_8) {
                env_8.error = e_8;
                env_8.hasError = true;
            }
            finally {
                const result_5 = __disposeResources(env_8);
                if (result_5)
                    await result_5;
            }
        }
        const result = await riskyOp();
        expect(result).toBeInstanceOf(Error);
        expect(log).toMatchInlineSnapshot(`
      [
        "released",
      ]
    `);
    });
});
